1214:                        let name = &name_bytes[..name_end];
1215:                        let child_mask = libc::IN_ATTRIB
1216:                            | libc::IN_CLOSE_WRITE
1217:                            | libc::IN_CREATE
1218:                            | libc::IN_DELETE
1219:                            | libc::IN_MOVED_FROM
1220:                            | libc::IN_MOVED_TO
1221:                            | libc::IN_MODIFY;
